#include "environment_asset.h"
#include <cstdio>
int main(int argc,char**argv){@autoreleasepool{if(argc!=3)return 2;auto asset=ssx::loadOriginalEnvironmentAsset([NSString stringWithUTF8String:argv[1]]);if(!asset)return 3;NSData*d=[NSData dataWithContentsOfFile:[NSString stringWithUTF8String:argv[2]]];NSArray* cases=[NSJSONSerialization JSONObjectWithData:d options:0 error:nil];for(NSDictionary* c in cases){ssx::OriginalEnvironmentState state;for(unsigned k=0;k<4;++k){state.ambient[k]=[c[@"old_ambient"][k]floatValue];state.ratio[k]=[c[@"old_ratio"][k]floatValue];}ssx::OriginalEnvironmentFrame f;f.groundPatch=asset->patch([c[@"resource"]unsignedIntValue]);f.u=[c[@"u"]floatValue];f.v=[c[@"v"]floatValue];asset->update(state,f);float error=0;for(unsigned k=0;k<4;++k)error=std::max(error,std::abs(state.ambient[k]-[c[@"expected_ambient"][k]floatValue]));printf("%s ambient %.9g %.9g %.9g maxerror %.9g\n",[c[@"name"]UTF8String],state.ambient[1],state.ambient[2],state.ambient[3],error);if(error!=0)return 4;}}}
